<section class="admin-section container"><h1>Mi biblioteca</h1><p>Hasta 100 elementos recientes por sección. El historial conserva las últimas 100 consultas de tu cuenta Premium; puedes borrarlo cuando quieras.</p><div class="dashboard-grid">
<section class="dashboard-panel"><h2>Favoritos</h2><ul class="dashboard-list"><?php foreach($library['favorites'] as $row): ?><li><a href="<?= e(url('mi-checklist?slug='.$row['slug'])) ?>"><?= e($row['nombre']) ?></a></li><?php endforeach; ?></ul><?php if($library['favorites']===[]): ?><p>Aún no guardaste favoritos disponibles.</p><?php endif; ?></section>
<section class="dashboard-panel"><h2>Rutas guardadas</h2><ul class="dashboard-list"><?php foreach($library['routes'] as $row): ?><li><a href="<?= e(url('ruta?id='.$row['id'])) ?>"><?= e($row['nombre']) ?></a></li><?php endforeach; ?></ul><?php if($library['routes']===[]): ?><p>Aún no guardaste rutas publicadas.</p><?php endif; ?></section>
<section class="dashboard-panel"><h2>Historial de consultas</h2><ul class="dashboard-list"><?php foreach($library['history'] as $row): ?><li><a href="<?= e(url('buscar?q='.rawurlencode($row['consulta']))) ?>"><?= e($row['consulta']) ?></a><span><?= e(local_datetime($row['fecha'])) ?></span></li><?php endforeach; ?></ul><?php if($library['history']===[]): ?><p>No hay consultas guardadas.</p><?php endif; ?><form method="post" action="<?= e(url('mi-biblioteca/borrar-historial')) ?>"><?= csrf_field() ?><button class="button button-secondary">Borrar mi historial</button></form></section>
</div></section>
